//! Rust ports of two Mindustry CPU hot paths, exposed to Java over JNI:
//! - `mindustry.ai.Pathfinder` flow-field computation (this module);
//! - `mindustry.async.AvoidanceProcess` unit avoidance mask (`avoidance`).
//!
//! The Java pathfinder updates the frontier incrementally with an 8ms budget on a
//! dedicated thread. This port computes the *whole* field in one pass, so a single JNI
//! call amortizes the boundary crossing over hundreds of thousands of tiles.
//!
//! The packed tile format is generated by the `@Struct` annotation processor from
//! `PathTileStruct`: field offsets start at the least significant bit, `@StructField(8)`
//! fields consume 8 bits, booleans consume one bit each, in declaration order.

mod jni;
pub mod avoidance;

use std::collections::VecDeque;

pub const IMPASSABLE: i32 = -1;

// PathTileStruct bit offsets.
const BIT_SOLID: u32 = 16;
const BIT_LIQUID: u32 = 17;
const BIT_LEG_SOLID: u32 = 18;
const BIT_NEAR_LIQUID: u32 = 19;
const BIT_NEAR_GROUND: u32 = 20;
const BIT_NEAR_SOLID: u32 = 21;
const BIT_DEEP: u32 = 23;
const BIT_DAMAGES: u32 = 24;
const BIT_ALL_DEEP: u32 = 25;
const BIT_TEAM_PASSABLE: u32 = 27;

#[inline]
const fn health(t: u32) -> i32 {
    (t & 0xff) as i32
}

#[inline]
const fn team(t: u32) -> i32 {
    ((t >> 8) & 0xff) as i32
}

#[inline]
const fn bit(t: u32, offset: u32) -> bool {
    (t & (1u32 << offset)) != 0
}

/// Mirrors `Pathfinder.costTypes` (indices 0..5). `cost_type` values outside that range
/// behave like the flat `costNone` function, which is what Java does for unused slots.
pub fn tile_cost(team_arg: i32, tile: i32, cost_type: i32) -> i32 {
    let t = tile as u32;
    let hp = health(t);
    let tid = team(t);
    let solid = bit(t, BIT_SOLID);
    let liquid = bit(t, BIT_LIQUID);
    let leg_solid = bit(t, BIT_LEG_SOLID);
    let near_liquid = bit(t, BIT_NEAR_LIQUID);
    let near_ground = bit(t, BIT_NEAR_GROUND);
    let near_solid = bit(t, BIT_NEAR_SOLID);
    let deep = bit(t, BIT_DEEP);
    let damages = bit(t, BIT_DAMAGES);
    let all_deep = bit(t, BIT_ALL_DEEP);
    let team_passable = bit(t, BIT_TEAM_PASSABLE);

    let bonus = |flag: bool, amount: i32| -> i32 {
        if flag {
            amount
        } else {
            0
        }
    };

    match cost_type {
        // ground
        0 => {
            if all_deep || (((tid == team_arg && !team_passable) || tid == 0) && solid) {
                return IMPASSABLE;
            }
            1 + hp * 5
                + bonus(near_solid, 2)
                + bonus(near_liquid, 6)
                + bonus(deep, 6000)
                + bonus(damages, 30)
        }
        // legs
        1 => {
            if leg_solid {
                return IMPASSABLE;
            }
            1 + bonus(deep, 6000) + bonus(solid, 5)
        }
        // naval
        2 => {
            let base = if !liquid || (solid && (tid == team_arg || tid == 0)) {
                7000
            } else {
                1 + hp * 5
            };
            base + bonus(near_ground || near_solid, 14)
                + if deep { 0 } else { 1 }
                + bonus(damages, 35)
        }
        // neoplasm
        3 => {
            if deep || (tid == 0 && solid) {
                return IMPASSABLE;
            }
            1 + hp * 3 + bonus(near_solid, 2) + bonus(near_liquid, 2)
        }
        // none: flat cost
        4 => 1,
        // hover
        5 => {
            if ((tid == team_arg && !team_passable) || tid == 0) && solid {
                return IMPASSABLE;
            }
            1 + hp * 5 + bonus(near_solid, 2)
        }
        _ => 1,
    }
}

/// Everything `build` needs. The JNI layer copies Java arrays into owned buffers first,
/// so a failed build never leaves partially mutated Java state behind.
pub struct BuildParams<'a> {
    pub tiles: &'a [i32],
    pub weights: &'a mut [i32],
    pub searches: &'a mut [i16],
    pub targets: &'a [i32],
    pub team: i32,
    pub cost_type: i32,
    pub search: i32,
    pub width: usize,
    pub height: usize,
}

/// Computes a complete flow field from `targets`, faithfully following
/// `Pathfinder.updateTargets` + `Pathfinder.updateFrontier` (without the time slicing).
/// Returns `false` for invalid dimensions or a runaway frontier, so Java can fall back.
pub fn build(p: BuildParams<'_>) -> bool {
    let len = match p.width.checked_mul(p.height) {
        Some(value) => value,
        None => return false,
    };
    if len == 0 || p.tiles.len() < len || p.weights.len() < len || p.searches.len() < len {
        return false;
    }

    let search_short = p.search as i16;
    let mut frontier: VecDeque<usize> = VecDeque::new();

    for &pos in p.targets {
        if pos < 0 {
            continue;
        }
        let index = pos as usize;
        if index >= len {
            continue;
        }
        p.weights[index] = 0;
        p.searches[index] = search_short;
        // IntQueue.addFirst / removeLast is FIFO.
        frontier.push_front(index);
    }

    let max_steps = len.saturating_mul(64).max(1024);
    let mut steps: usize = 0;
    let deltas: [(i32, i32); 4] = [(-1, 0), (1, 0), (0, -1), (0, 1)];
    let w = p.width as i32;
    let h = p.height as i32;

    while let Some(tile) = frontier.pop_back() {
        steps += 1;
        if steps > max_steps {
            return false;
        }

        let cost = p.weights[tile];
        if cost == IMPASSABLE {
            continue;
        }

        let x = (tile % p.width) as i32;
        let y = (tile / p.width) as i32;

        for (dx, dy) in deltas {
            let nx = x + dx;
            let ny = y + dy;
            if nx < 0 || ny < 0 || nx >= w || ny >= h {
                continue;
            }
            let next = (nx + ny * w) as usize;
            let other = tile_cost(p.team, p.tiles[next], p.cost_type);
            let candidate = cost.wrapping_add(other);

            if other != IMPASSABLE
                && (p.weights[next] > candidate || (p.searches[next] as i32) < p.search)
            {
                p.weights[next] = candidate;
                p.searches[next] = search_short;
                frontier.push_front(next);
            }
        }
    }

    true
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tile(hp: u32, team: u32, bits: &[u32]) -> i32 {
        let mut value = (hp & 0xff) | ((team & 0xff) << 8);
        for &offset in bits {
            value |= 1u32 << offset;
        }
        value as i32
    }

    fn run(
        tiles: &[i32],
        w: usize,
        h: usize,
        targets: &[i32],
        cost_type: i32,
        team: i32,
        search: i32,
    ) -> Vec<i32> {
        let mut weights = vec![IMPASSABLE; w * h];
        let mut searches = vec![0i16; w * h];
        assert!(build(BuildParams {
            tiles,
            weights: &mut weights,
            searches: &mut searches,
            targets,
            team,
            cost_type,
            search,
            width: w,
            height: h,
        }));
        weights
    }

    /// Slow Bellman-Ford reference: relax every edge until nothing changes.
    fn reference(
        tiles: &[i32],
        w: usize,
        h: usize,
        targets: &[i32],
        cost_type: i32,
        team: i32,
    ) -> Vec<i32> {
        let mut dist = vec![IMPASSABLE; w * h];
        for &pos in targets {
            if pos >= 0 && (pos as usize) < dist.len() {
                dist[pos as usize] = 0;
            }
        }
        loop {
            let mut changed = false;
            for y in 0..h {
                for x in 0..w {
                    let from = x + y * w;
                    if dist[from] == IMPASSABLE {
                        continue;
                    }
                    for (dx, dy) in [(-1isize, 0isize), (1, 0), (0, -1), (0, 1)] {
                        let nx = x as isize + dx;
                        let ny = y as isize + dy;
                        if nx < 0 || ny < 0 || nx >= w as isize || ny >= h as isize {
                            continue;
                        }
                        let to = nx as usize + ny as usize * w;
                        let cost = tile_cost(team, tiles[to], cost_type);
                        if cost == IMPASSABLE {
                            continue;
                        }
                        let candidate = dist[from].wrapping_add(cost);
                        if dist[to] == IMPASSABLE || dist[to] > candidate {
                            dist[to] = candidate;
                            changed = true;
                        }
                    }
                }
            }
            if !changed {
                break;
            }
        }
        dist
    }

    #[test]
    fn packed_tile_accessors_match_java_layout() {
        let packed = tile(37, 9, &[BIT_SOLID, BIT_NEAR_LIQUID, BIT_TEAM_PASSABLE]);
        assert_eq!(health(packed as u32), 37);
        assert_eq!(team(packed as u32), 9);
        assert!(bit(packed as u32, BIT_SOLID));
        assert!(bit(packed as u32, BIT_NEAR_LIQUID));
        assert!(bit(packed as u32, BIT_TEAM_PASSABLE));
        assert!(!bit(packed as u32, BIT_DEEP));
    }

    #[test]
    fn cost_functions_match_java_vectors() {
        let plain = tile(0, 1, &[]);
        assert_eq!(tile_cost(1, plain, 0), 1); // ground
        assert_eq!(tile_cost(1, plain, 1), 1); // legs
        assert_eq!(tile_cost(1, plain, 2), 7001); // naval, not liquid
        assert_eq!(tile_cost(1, plain, 3), 1); // neoplasm
        assert_eq!(tile_cost(1, plain, 4), 1); // none
        assert_eq!(tile_cost(1, plain, 5), 1); // hover

        // health 10, nearSolid, nearLiquid, deep, damages: 1 + 50 + 2 + 6 + 6000 + 30
        let loaded = tile(
            10,
            1,
            &[BIT_NEAR_SOLID, BIT_NEAR_LIQUID, BIT_DEEP, BIT_DAMAGES],
        );
        assert_eq!(tile_cost(1, loaded, 0), 6089);
        assert_eq!(tile_cost(1, loaded, 5), 53);

        // deep blocks the neoplasm cost type
        assert_eq!(tile_cost(1, loaded, 3), IMPASSABLE);

        // allDeep blocks ground units
        let all_deep = tile(0, 1, &[BIT_ALL_DEEP]);
        assert_eq!(tile_cost(1, all_deep, 0), IMPASSABLE);

        // a solid tile of another team is passable, an own solid tile is not
        let enemy = tile(0, 2, &[BIT_SOLID]);
        assert_eq!(tile_cost(1, enemy, 0), 1);
        assert_eq!(tile_cost(2, enemy, 0), IMPASSABLE);
        let own = tile(0, 1, &[BIT_SOLID]);
        assert_eq!(tile_cost(1, own, 0), IMPASSABLE);
        assert_eq!(
            tile_cost(1, tile(0, 1, &[BIT_SOLID, BIT_TEAM_PASSABLE]), 0),
            1
        );

        // legs: legSolid blocks, solid adds 5
        assert_eq!(tile_cost(1, tile(0, 1, &[BIT_LEG_SOLID]), 1), IMPASSABLE);
        assert_eq!(tile_cost(1, own, 1), 6);
    }

    #[test]
    fn flat_grid_is_manhattan_distance() {
        let (w, h) = (9, 9);
        let tiles = vec![tile(0, 1, &[]); w * h];
        let weights = run(&tiles, w, h, &[(4 + 4 * w) as i32], 4, 1, 1);
        for y in 0..h {
            for x in 0..w {
                let expected = (x as i32 - 4).abs() + (y as i32 - 4).abs();
                assert_eq!(weights[x + y * w], expected, "at {x},{y}");
            }
        }
    }

    #[test]
    fn walls_are_impassable() {
        let (w, h) = (7, 7);
        let mut tiles = vec![tile(0, 1, &[]); w * h];
        // vertical allDeep wall, with one gap at y == 0
        for y in 1..h {
            tiles[3 + y * w] = tile(0, 1, &[BIT_ALL_DEEP]);
        }
        let weights = run(&tiles, w, h, &[0], 0, 1, 1);
        assert_eq!(weights[0], 0);
        for y in 1..h {
            assert_eq!(weights[3 + y * w], IMPASSABLE, "wall at y={y}");
        }
        // the right side is reachable only around the top gap: 3 + 1 + 6 steps
        assert_eq!(weights[4 + 6 * w], 10);
        assert_eq!(weights[1], 1);
    }

    #[test]
    fn matches_reference_relaxation_on_pseudo_random_maps() {
        let mut seed: u32 = 0x5eed_1234;
        let mut next = || {
            seed = seed.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
            seed
        };

        for cost_type in [0, 1, 2, 3, 4, 5] {
            for _ in 0..12 {
                let (w, h) = (11usize, 9usize);
                // fully random packed tiles exercise every cost bit
                let tiles: Vec<i32> = (0..w * h).map(|_| next() as i32).collect();
                let targets = [(next() % (w * h) as u32) as i32];
                let expected = reference(&tiles, w, h, &targets, cost_type, 2);
                let actual = run(&tiles, w, h, &targets, cost_type, 2, 1);
                assert_eq!(
                    actual, expected,
                    "cost_type={cost_type}, target={targets:?}"
                );
            }
        }
    }

    #[test]
    fn rejects_invalid_dimensions() {
        let tiles = [0i32; 4];
        let mut weights = [0i32; 4];
        let mut searches = [0i16; 4];
        assert!(!build(BuildParams {
            tiles: &tiles,
            weights: &mut weights,
            searches: &mut searches,
            targets: &[0],
            team: 1,
            cost_type: 4,
            search: 1,
            width: 0,
            height: 4,
        }));
        assert!(!build(BuildParams {
            tiles: &tiles,
            weights: &mut weights,
            searches: &mut searches,
            targets: &[0],
            team: 1,
            cost_type: 4,
            search: 1,
            width: 100,
            height: 100,
        }));
    }
}
